// ── Turn the model output into a branded HTML email ────────────────
const d = $('Normalise submission').first().json;
const res = $input.first().json;

// Pull the text blocks out of the Anthropic response, whatever else came back.
let body = '';
try {
  if (Array.isArray(res.content)) {
    body = res.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n\n').trim();
  }
} catch (e) { body = ''; }

const generated = body.length > 200;

// If the model failed, the reader still gets their score and a static plan.
const fallback = [
'## The shape of your build',
'You scored ' + d.overall + ' out of 100. Ambition sits at ' + d.ambition + ' and capacity at ' + d.capacity + '. Your weakest dimension is ' + d.weakest + '.',
'',
'## Your binding constraint',
d.weakest + ' is the dimension holding the rest back. Effort spent anywhere else returns very little until it moves.',
'',
'## Thirty days',
'1. Write down, on one page, what is true about ' + d.weakest + ' in your business today. Numbers, not adjectives.',
'2. Name the single thing in that dimension that only you can currently do, and hand one piece of it to someone else this month.',
'3. Book a date thirty days out to retake the audit and compare the two scores.',
'',
'## The question to sit with',
'What would have to be true about ' + d.weakest + ' before the rest of this business could grow without you?'
].join('\n');

const src = generated ? body : fallback;

// Minimal, deliberate markdown to HTML. Handles H2, ordered lists, bold, paragraphs.
const esc = (t) => t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const inline = (t) => esc(t).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

const H2 = 'font:600 20px/1.25 Georgia,serif;color:#172A46;margin:32px 0 10px;';
const P  = 'font:400 16px/1.6 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#26364f;margin:0 0 14px;';
const LI = P + 'margin:0 0 12px;';

const lines = src.split(/\r?\n/);
const out = [];
let list = [];
const flush = () => {
  if (!list.length) return;
  out.push('<ol style="padding-left:22px;margin:0 0 18px;">' + list.join('') + '</ol>');
  list = [];
};
for (const line of lines) {
  const t = line.trim();
  if (!t) { flush(); continue; }
  if (t.startsWith('## ')) { flush(); out.push('<h2 style="' + H2 + '">' + inline(t.slice(3)) + '</h2>'); continue; }
  if (/^\d+[.)]\s/.test(t)) { list.push('<li style="' + LI + '">' + inline(t.replace(/^\d+[.)]\s/,'')) + '</li>'); continue; }
  flush();
  out.push('<p style="' + P + '">' + inline(t) + '</p>');
}
flush();

// Dimension bars, table-based so they survive Outlook and Gmail.
const bar = (label, score) => {
  const w = Math.max(score, 2);
  const fill = label === d.weakest ? '#8C3A2B' : '#172A46';
  return '<tr>'
    + '<td style="font:500 14px/1.4 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#4A5B75;padding:6px 12px 6px 0;white-space:nowrap;">' + label + '</td>'
    + '<td style="width:100%;padding:6px 10px 6px 0;">'
    +   '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#E4DFD4;"><tr>'
    +     '<td style="width:' + w + '%;background:' + fill + ';height:6px;font-size:0;line-height:0;">&nbsp;</td>'
    +     '<td style="font-size:0;line-height:0;">&nbsp;</td>'
    +   '</tr></table>'
    + '</td>'
    + '<td style="font:600 15px/1.4 Georgia,serif;color:#9A7434;padding:6px 0;">' + score + '</td>'
    + '</tr>';
};

const bars = [
  bar('Vision', d.vision), bar('Scale', d.scale), bar('Impact', d.impact),
  bar('Systems', d.systems), bar('Legacy', d.legacy)
].join('');

const html = [
'<!doctype html><html><body style="margin:0;padding:0;background:#FBF9F4;">',
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#FBF9F4;padding:28px 12px;"><tr><td align="center">',
'<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:#FFFFFF;border:1px solid #E4DFD4;">',
'<tr><td style="padding:22px 28px 16px;border-bottom:1px solid #E4DFD4;">',
  '<div style="font:600 15px/1.3 Georgia,serif;color:#172A46;">The Builder\'s Handbook</div>',
  '<div style="font:400 13px/1.3 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#9A7434;">Ideas. Insights. Impact.</div>',
'</td></tr>',
'<tr><td style="padding:26px 28px 6px;">',
  '<div style="font:400 13px/1.3 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#4A5B75;">' + d.name + ', your Builder\'s Vision Audit</div>',
  '<div style="font:600 56px/1 Georgia,serif;color:#172A46;letter-spacing:-1px;padding:6px 0 0;">' + d.overall + '<span style="font-size:18px;color:#4A5B75;">/100</span></div>',
  '<div style="font:600 26px/1.15 Georgia,serif;color:#172A46;padding:10px 0 0;">' + d.archetype + '</div>',
  '<div style="font:400 15px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#4A5B75;padding:8px 0 0;">Ambition ' + d.ambition + ' &nbsp;·&nbsp; Capacity ' + d.capacity + ' &nbsp;·&nbsp; Weakest dimension: ' + d.weakest + '</div>',
'</td></tr>',
'<tr><td style="padding:20px 28px 4px;">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' + bars + '</table>',
'</td></tr>',
'<tr><td style="padding:0 28px 8px;">' + out.join('') + '</td></tr>',
'<tr><td style="padding:8px 28px 30px;">',
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td style="background:#172A46;padding:13px 22px;">',
  '<a href="https://www.thebuildershandbook.com" style="font:600 15px -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#FFFFFF;text-decoration:none;">Read The Builder\'s Handbook</a>',
  '</td></tr></table>',
'</td></tr>',
'<tr><td style="padding:16px 28px 22px;border-top:1px solid #E4DFD4;font:400 12px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#8A8578;">',
  'You asked for this report at www.thebuildershandbook.com. Retake the audit in ninety days and compare the two scores.',
'</td></tr>',
'</table></td></tr></table></body></html>'
].join('');

const subject = d.archetype
  ? (d.name !== 'there' ? d.name + ', your Vision Audit: ' + d.archetype : 'Your Vision Audit: ' + d.archetype)
  : 'Your Builder\'s Vision Audit';

return [{ json: { html, subject, generated, to: d.email } }];
